import{_ as a,y as n,a as r,o as i,a2 as e,D as o}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Taxes","description":"","frontmatter":{},"headers":[],"relativePath":"configure/taxes.md","filePath":"configure/taxes.md","lastUpdated":1789441803000}'),l={name:"configure/taxes.md"};function g(d,t,h,c,p,u){const s=n("ImagePopup");return i(),r("div",null,[t[0]||(t[0]=e('<h1 id="taxes" tabindex="-1">Taxes <a class="header-anchor" href="#taxes" aria-label="Permalink to &quot;Taxes&quot;">​</a></h1><p>This screen decides how tax is calculated and how it&#39;s shown. The tax categories and tax rates themselves are created under <strong>Settings &gt;&gt; Taxes</strong>; see <a href="./../settings/taxes.html">Taxes</a>. All settings on this screen apply to the whole store.</p><h2 id="choose-the-tax-categories" tabindex="-1">Choose the tax categories <a class="header-anchor" href="#choose-the-tax-categories" aria-label="Permalink to &quot;Choose the tax categories&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Taxes</strong>.</li><li>In <strong>Tax Categories</strong>, choose the <strong>Shipping Tax Category</strong>.</li><li>Choose the <strong>Product Default Tax Category</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),o(s,{src:"/images/configure/taxes-calculation.png",alt:"Tax Categories and Calculation Settings sections of the Taxes screen"}),t[1]||(t[1]=e('<p><strong>Shipping Tax Category:</strong> The tax category used to tax shipping. If none is chosen, shipping isn&#39;t taxed.</p><p><strong>Product Default Tax Category:</strong> The tax category used for products that don&#39;t have a tax category of their own. If none is chosen, those products aren&#39;t taxed.</p><h2 id="decide-how-tax-is-calculated" tabindex="-1">Decide how tax is calculated <a class="header-anchor" href="#decide-how-tax-is-calculated" aria-label="Permalink to &quot;Decide how tax is calculated&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Taxes</strong>.</li><li>In <strong>Calculation Settings</strong>, choose the options described below.</li><li>Click <strong>Save Configuration</strong>.</li></ol><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Calculation Based On</strong></td><td>The address whose tax rates apply. <strong>Shipping Address</strong>, the default, uses the shipping address for products that are shipped, and the billing address for virtual, downloadable and booking products. <strong>Billing Address</strong> always uses the billing address. <strong>Shipping Origin</strong> uses the address set under <a href="./shipping.html">Shipping Settings</a>.</td></tr><tr><td><strong>Product Prices</strong></td><td><strong>Excluding Tax</strong>, the default, when the prices you enter don&#39;t include tax, so tax is added on top. <strong>Including Tax</strong> when they already include it, so the tax is worked out from the price and shoppers pay the price as entered.</td></tr><tr><td><strong>Shipping Prices</strong></td><td>The same choice for shipping rates.</td></tr><tr><td><strong>Apply Tax On</strong></td><td><strong>After Discount</strong>, the default, calculates tax on the price after cart rule discounts. <strong>Before Discount</strong> calculates it on the original price. For products it applies only while <strong>Product Prices</strong> is <strong>Excluding Tax</strong>, and for shipping only while <strong>Shipping Prices</strong> is <strong>Excluding Tax</strong>.</td></tr></tbody></table><h2 id="set-a-default-destination" tabindex="-1">Set a default destination <a class="header-anchor" href="#set-a-default-destination" aria-label="Permalink to &quot;Set a default destination&quot;">​</a></h2><p>Tax is calculated before a shopper enters an address, for example in the cart. Until then, a signed-in customer&#39;s default address is used if they have one. Otherwise the default destination is used.</p><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Taxes</strong>.</li><li>In <strong>Default Destination Calculation</strong>, choose the <strong>Default Country</strong>.</li><li>Choose the <strong>Default State</strong>.</li><li>Enter the <strong>Default Post Code</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',8)),o(s,{src:"/images/configure/taxes-display.png",alt:"Default Destination Calculation and tax display sections of the Taxes screen"}),t[2]||(t[2]=e('<p>If <strong>Default Country</strong> is empty, tax isn&#39;t calculated until the shopper&#39;s address is known.</p><h2 id="choose-how-tax-is-displayed" tabindex="-1">Choose how tax is displayed <a class="header-anchor" href="#choose-how-tax-is-displayed" aria-label="Permalink to &quot;Choose how tax is displayed&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Taxes</strong>.</li><li>In <strong>Shopping Cart Display Settings</strong>, choose the <strong>Display Prices</strong>.</li><li>Choose the <strong>Display Subtotal</strong>.</li><li>Choose the <strong>Display Shipping Amount</strong>.</li><li>Switch <strong>Show Tax Breakdown</strong> on or off.</li><li>In <strong>Orders, Invoices, Refunds Display Settings</strong>, choose the <strong>Display Prices</strong>.</li><li>Choose the <strong>Display Subtotal</strong>.</li><li>Choose the <strong>Display Shipping Amount</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>Each <strong>Display</strong> setting has these options:</p><ul><li><strong>Excluding Tax</strong>: the amount without tax. This is the default.</li><li><strong>Including Tax</strong>: the amount with tax.</li><li><strong>Excluding and Including Both</strong>: both amounts.</li></ul><p><strong>Shopping Cart Display Settings</strong> apply to the cart, the mini cart, the checkout summary and the cart of an order you create in the admin panel. <strong>Orders, Invoices, Refunds Display Settings</strong> apply to orders, invoices and refunds in the admin panel, to a customer&#39;s orders on the storefront, and to the order emails and invoice PDF. How tax appears on an order is described in <a href="./../orders/orders.html#order-items-and-totals">Orders</a>.</p><p><strong>Show Tax Breakdown</strong> lists the tax for each product and tax rate in the cart and checkout summaries. It&#39;s meant for checking your tax setup.</p>',7))])}const T=a(l,[["render",g]]);export{f as __pageData,T as default};
